-- Question bank for unit reviews. Administrators add to it from the admin area.
CREATE TABLE IF NOT EXISTS review_questions (
  id SERIAL PRIMARY KEY,
  unit_id VARCHAR(120) NOT NULL,
  type VARCHAR(30) NOT NULL CHECK (type IN ('multiple_choice', 'word_match', 'word_scramble')),
  content JSONB NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_review_questions_unit ON review_questions(unit_id) WHERE enabled;

